  const basis = [
    (article.title ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(),
    (article.summary_raw ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 300),
